            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0xF2148F0EFD0B81A5ULL) ^ aOrbiterUpdateSaltB[((aIndex + 14U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x4B3A98327DAE5123ULL), 35U);
