            //
            aWandererE = aWandererE + ((((RotL64(aPrevious, 53U) + aOrbiterE) + RotL64(aOrbiterK, 41U)) + RotL64(aCarry, 27U)) + aWandererUpdateSaltB[((aIndex + 7U)) & S_SALT1]);
