            aOrbiterK = (((aWandererC + RotL64(aIngress, 48U)) + 0x87835A3F918CEC77ULL) + aOrbiterAssignSaltE[(((31U - aIndex) + 8U)) & S_SALT1]) + aNonceWordA;
