            aOrbiterB = (aWandererE + RotL64(aCross, 53U)) + 0xC960527C17208ACBULL;
            aOrbiterE = (((aWandererG + RotL64(aIngress, 6U)) + RotL64(aCarry, 35U)) + 0x77D3864F29012D56ULL) + aNonceWordC;
            aOrbiterC = ((aWandererJ + RotL64(aPrevious, 41U)) + RotL64(aCarry, 5U)) + 0x820E20A7C12BF638ULL;
            //
            aOrbiterK = (((aOrbiterK + aOrbiterG) + 0x1CAEF1D75CA1C3B7ULL) + aOrbiterUpdateSaltD[(((31U - aIndex) + 21U)) & S_SALT1]) + aNonceWordJ;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x53586BD025BBAB27ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x46A6519CEB7B7F57ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x02787D08252E1F1AULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x70EE9C79AA4CA655ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x17E8C6CA45371C2FULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x65CE563AD6719548ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0xCF492B9112E9B5E0ULL) ^ aNonceWordL;
            aOrbiterB = RotL64((aOrbiterB * 0x24CEB9496CBD4181ULL), 23U);
