            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x0812F21CFDC61514ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x3F8D26BA19138EB4ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x6D978425A157DBABULL), 29U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0xA748AB5769F8B16EULL) + aPhaseBOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x82B732FD7A7EB253ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x93DC42395B6A367DULL), 37U);
