            //
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 37U) + aOrbiterH) + RotL64(aOrbiterK, 51U));
            aWandererA = aWandererA + (((RotL64(aCross, 57U) + RotL64(aOrbiterH, 22U)) + aOrbiterI) + RotL64(aCarry, 21U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 11U) + RotL64(aOrbiterC, 57U)) + aOrbiterB);
            aWandererD = aWandererD + ((((RotL64(aScatter, 47U) + aOrbiterG) + RotL64(aOrbiterB, 29U)) + RotL64(aCarry, 37U)) + aPhaseBWandererUpdateSaltB[((aIndex + 11U)) & S_SALT1]);
