            aWandererE = aWandererE + ((RotL64(aScatter, 3U) + aOrbiterJ) + RotL64(aOrbiterC, 37U));
            aWandererC = aWandererC ^ (((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterB, 11U)) + aPhaseBWandererUpdateSaltF[((aIndex + 13U)) & S_SALT1]);
