            //
            aOrbiterG = ((aWandererG + RotL64(aPrevious, 23U)) + 0x1C8452CD1A7C345CULL) + aPhaseAOrbiterAssignSaltA[((aIndex + 22U)) & S_SALT1];
            aOrbiterK = (((aWandererK + RotL64(aCross, 29U)) + RotL64(aCarry, 5U)) + 0xCF509F51968DECA9ULL) + aPhaseAOrbiterAssignSaltB[((aIndex + 6U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aScatter, 48U)) + RotL64(aCarry, 19U)) + 0x9675DA3C1266A98EULL;
            aOrbiterD = (aWandererJ + RotL64(aIngress, 11U)) + 0x91768DF302F60B03ULL;
