            aOrbiterB = RotL64((aOrbiterB * 0xED1F69F1141FA2E3ULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x5EF786F5A0F468B7ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x2E7212345D733D7DULL;
