            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 5540U)) & S_BLOCK1], 19U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 7981U)) & S_BLOCK1], 10U));
            aCross ^= RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 10176U)) & S_BLOCK1], 35U);
