            aOrbiterG = ((aWandererB + RotL64(aScatter, 37U)) + 0x4A449753A5FC6509ULL) + aPhaseAOrbiterAssignSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 21U)) + RotL64(aCarry, 29U)) + 0xC6BC1510B24AF37EULL;
            aOrbiterA = ((aWandererE + RotL64(aIngress, 29U)) + RotL64(aCarry, 53U)) + 0x745B2C7519495257ULL;
            aOrbiterB = ((aWandererK + RotL64(aScatter, 51U)) + 0x4CEC3A10C30C0A6FULL) + aPhaseAOrbiterAssignSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterD = (aWandererA + RotL64(aIngress, 13U)) + 0x6816AAE370CEAB89ULL;
            aOrbiterF = (aWandererI + RotL64(aPrevious, 5U)) + 0x93ED5D2FDB096E1DULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x0A3E08E90214C538ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x9583C710CD09FDFBULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1E22DB18A583FA93ULL), 11U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x7D8BFAA08BE1D781ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0xD144A770B0571067ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF78F3720E7086FDDULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x812289C630B314C9ULL;
