            aIngress = (RotL64(aHeartLaneA[((aIndex + 3452U)) & S_BLOCK1], 5U) ^ RotL64(aHeartLaneB[((aIndex + 7208U)) & S_BLOCK1], 44U));
            aIngress ^= (RotL64(aSpiritLaneB[((aIndex + 2531U)) & S_BLOCK1], 21U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 2396U)) & S_BLOCK1], 13U));
