            //
            aOrbiterB = (aWandererH + RotL64(aIngress, 57U)) + 0x0A956F4606129AC5ULL;
            aOrbiterI = (((aWandererA + RotL64(aScatter, 11U)) + RotL64(aCarry, 3U)) + 0x751522CB514A073AULL) + aPhaseAOrbiterAssignSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = (aWandererJ + RotL64(aCross, 51U)) + 0xF32F611CB761CF01ULL;
            aOrbiterH = ((aWandererK + RotL64(aPrevious, 19U)) + RotL64(aCarry, 47U)) + 0xF838375946EB797CULL;
            aOrbiterA = ((aWandererG + RotL64(aCross, 27U)) + RotL64(aCarry, 29U)) + 0x739042EDFAD6BC63ULL;
            aOrbiterJ = (aWandererF + RotL64(aPrevious, 34U)) + 0x8B921CBB0454998AULL;
            aOrbiterG = ((aWandererD + RotL64(aScatter, 41U)) + 0x8973883F864E94A9ULL) + aPhaseAOrbiterAssignSaltE[((aIndex + 25U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xBD18B18B95A9C8B7ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xF975F0735CEC837DULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8C33F28C4561CF2BULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xB283FA92385DDD19ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x268B95C66A9DEAC8ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x39612276489B2DB1ULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x8F563C1549B94095ULL) + aPhaseAOrbiterUpdateSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0xDF210371B09A1110ULL) ^ aPhaseAOrbiterUpdateSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x78E6A0D7F61162B1ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x0C687A4BC115A3EFULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0xAE4DC69B21BB489CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1A95E9D8E9351525ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x3EF087B943875DA8ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x4221D82C7DA8C9FBULL) ^ aPhaseAOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x16676A8C2BD13C9DULL), 27U);
