            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x0FAE433626588AABULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x1F42AE5FB1CF1126ULL) ^ aPhaseAOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x18EB54ECBDEA253FULL), 5U);
            //
            aIngress = RotL64(aOrbiterD, 47U) ^ aOrbiterH;
