            //
            aWandererF = aWandererF + (((RotL64(aScatter, 27U) + aOrbiterG) + RotL64(aOrbiterD, 3U)) + RotL64(aCarry, 39U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 48U) + RotL64(aOrbiterA, 47U)) + aOrbiterB);
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 5U) + RotL64(aOrbiterI, 37U)) + aOrbiterG) + aPhaseAWandererUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1]);
