            aOrbiterG = (aWandererH + RotL64(aScatter, 39U)) + 0x3CABE35BC4C1F0EDULL;
            aOrbiterE = ((aWandererI + RotL64(aIngress, 51U)) + 0x11866B292DBAB199ULL) + aPhaseBOrbiterAssignSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterF = (aWandererC + RotL64(aCross, 19U)) + 0xF03D7DFD0A8C0E6BULL;
            aOrbiterC = (((aWandererF + RotL64(aScatter, 5U)) + RotL64(aCarry, 57U)) + 0x14644E4C20A62EB1ULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterJ = (aWandererE + RotL64(aIngress, 29U)) + 0xE3B08ECB5EFA83B9ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x64416CF44C696EBCULL;
