            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x657B9B656B1799F9ULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xF520A6ABB391F0C5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1B8C6E16B2FC2561ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x3C6DE58C60388A9DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x3911D729FCE73307ULL;
