            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x7650D93DCF6E9389ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0x5078BC328B7BB5EEULL) ^ aPhaseBOrbiterUpdateSaltE[((aIndex + 14U)) & S_SALT1];
