            aOrbiterB = ((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 21U)) + 0x38860DEFD9EA3AE1ULL;
            aOrbiterE = (((aWandererK + RotL64(aScatter, 21U)) + RotL64(aCarry, 57U)) + 0x1718DEC14430F479ULL) + aPhaseDOrbiterAssignSaltB[((aIndex + 11U)) & S_SALT1];
